import{_ as a,a as t,b as o,c as s,d as n}from"./chunks/device-tablet-landscape.D4FvTdpl.js";import{_ as r,o as i,c as h,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const v=JSON.parse('{"title":"On Different Devices","description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…","frontmatter":{"description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…"},"headers":[],"relativePath":"guide/devices.md","filePath":"guide/devices.md","lastUpdated":1794780892000}'),p={name:"guide/devices.md"};function d(c,e,u,w,g,b){return i(),h("div",null,[...e[0]||(e[0]=[l('<h1 id="on-different-devices" tabindex="-1">On Different Devices <a class="header-anchor" href="#on-different-devices" aria-label="Permalink to &quot;On Different Devices&quot;">​</a></h1><p>One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen — they just move around. This page shows how the main windows rearrange at each size, with a real capture for each shape.</p><h2 id="pc-landscape-—-1440-px" tabindex="-1">PC, landscape — 1440 px <a class="header-anchor" href="#pc-landscape-—-1440-px" aria-label="Permalink to &quot;PC, landscape — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+a+'" alt="1440 px wide window with the library sidebar, three compare panes and the notes column"><figcaption>1440 px: sidebar on the left, three language panes in the middle, notes column on the right.</figcaption></figure><p>At 1440 px the sidebar (around 270 px), the compare stage and the notes column are all visible at once. The three language panes sit side by side, so a whole exchange fits without scrolling, and the notes column opens by default when the window starts wider than 1180 px — drag its splitter to widen it, or close it with <strong>Notes</strong> (<code>N</code>).</p><h2 id="pc-portrait-—-900-×-1200" tabindex="-1">PC, portrait — 900 × 1200 <a class="header-anchor" href="#pc-portrait-—-900-×-1200" aria-label="Permalink to &quot;PC, portrait — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="900 by 1200 narrow desktop window with the library collapsed into a drawer and the compare panes stacked"><figcaption>900 × 1200: sidebar folded into a drawer, one compare column, notes closed until you ask for them.</figcaption></figure><p>At 900 px the layout switches to its narrow mode: the library folds into a drawer behind the ☰ button, the compare panes stack in a single column, and the notes column starts closed — <strong>Notes</strong> brings it back. Toolbar groups drop their text labels, and the actions that no longer fit move under <strong>More</strong>.</p><h2 id="phone-portrait-—-390-×-844" tabindex="-1">Phone, portrait — 390 × 844 <a class="header-anchor" href="#phone-portrait-—-390-×-844" aria-label="Permalink to &quot;Phone, portrait — 390 × 844&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="390 by 844 window with the top bar and toolbar wrapped over several rows"><figcaption>390 × 844: the top bar wraps onto three rows and the toolbar onto several more; the touch layout shows one language lane at a time.</figcaption></figure><p>On a 390 px touch phone the top bar wraps into three rows — navigation and page controls, then interface language and export, then the <strong>Panels / Compare</strong> switch. The compare stage shows one language lane at a time. The language tab bar above the stage (JA / EN / ZH) picks which active language is in view; when more than one language is active you can also swipe left or right to switch, and the hint next to the tabs says so. The language toggles in the toolbar decide which languages are active in the first place. Toolbar groups wrap onto extra rows instead of scrolling out of reach; the library opens as a left drawer and notes as a full-width drawer. Turn the phone sideways and it uses the same two-lane touch layout as a portrait tablet.</p><h2 id="tablet-portrait-—-820-×-1180" tabindex="-1">Tablet, portrait — 820 × 1180 <a class="header-anchor" href="#tablet-portrait-—-820-×-1180" aria-label="Permalink to &quot;Tablet, portrait — 820 × 1180&quot;">​</a></h2><figure class="shot"><img src="'+s+'" alt="820 by 1180 window with the top bar on one row and the compare panes stacked"><figcaption>820 × 1180: top bar on one row, sidebar in a drawer; a mouse-driven window stacks the panes, while a touch tablet pairs them two per row.</figcaption></figure><p>KomaYomi picks the compare layout from the pointer type and the aspect ratio, not the width alone. In a fine-pointer window at 820 px the panes stack in a single column. On a touch tablet in portrait, each panel shows two language lanes side by side; when more than two languages are active, the tab bar above the stage chooses which pair is visible, starting from the focused language. Phones in landscape up to 900 px wide use the same two-lane layout. The top bar stays on one row, the sidebar stays a drawer, the toolbar wraps and folds the actions that no longer fit under <strong>More</strong>, and notes open as a drawer over the stage.</p><h2 id="tablet-landscape-—-1180-×-820" tabindex="-1">Tablet, landscape — 1180 × 820 <a class="header-anchor" href="#tablet-landscape-—-1180-×-820" aria-label="Permalink to &quot;Tablet, landscape — 1180 × 820&quot;">​</a></h2><figure class="shot"><img src="'+n+'" alt="1180 by 820 tablet window with the sidebar open and three language panes side by side"><figcaption>1180 × 820: sidebar open, three language panes side by side, notes as a drawer.</figcaption></figure><p>At 1180 px the sidebar (240 px) is back, and the three language panes sit in one row at roughly 290 px each. On a touch tablet in landscape, KomaYomi shows two lanes up to 900 px wide and three lanes above 900 px up to 1199 px; the language tab bar only appears when you have more languages enabled than there are lanes. Notes stay a drawer at this width and open over the stage. The toolbar keeps two rows — language and alignment controls on top, annotation tools below — while <strong>Export HTML</strong> stays in the top bar.</p><div class="info custom-block"><p class="custom-block-title">About the phone and portrait-tablet captures</p><p>The 390 × 844 and 820 × 1180 captures above were taken in a mouse-driven browser window, so they show the desktop stacking rule. On a touch phone or tablet KomaYomi uses the touch layouts described here: one lane on a phone, two side by side on a portrait tablet.</p></div><div class="tip custom-block"><p class="custom-block-title">Capturing your own layouts</p><p>Resize the browser window rather than zooming the page: the breakpoints follow the viewport width, and the notes column and sidebar only change places when the window itself crosses them.</p></div>',19)])])}const y=r(p,[["render",d]]);export{v as __pageData,y as default};
